#!/usr/bin/env node
/**
 * Deterministic source-native question screening from verified Schaff OCR.
 * Research-only. A nearby original-text window is NOT a verified answer;
 * not even a rhetorically shaped question is automatically Father-authored.
 *
 * Requires the two full-volume acquisition/section outputs generated by:
 *   node scripts/scripture-catena-schaff-ocr-ingest.mjs --volume all
 *   node scripts/scripture-catena-schaff-section-ingest.mjs
 */
import {readFileSync,writeFileSync,mkdirSync} from "node:fs";
import {join,resolve} from "node:path";
import {createHash} from "node:crypto";
const arg=(flag,fallback)=>{
 const i=process.argv.indexOf(flag);
 return i===-1?fallback:process.argv[i+1]
};
const sourceDir=resolve(arg("--source-dir","dist/schaff-original-ocr"));
const unitDir=resolve(arg("--unit-dir","dist/schaff-sectioned-research"));
const outDir=resolve(arg("--output-dir","dist/schaff-context-pilot"));
const sha=s=>createHash("sha256").update(s,"utf8").digest("hex");
const load=p=>JSON.parse(readFileSync(p,"utf8"));
const phrase=s=>s.replace(/\s+/g," ").trim();
const questionWords=/\b(?:why|how|wherefore|whence|what|whether|who|whom)\b/i;
const strong=/\b(?:but\s+why|but\s+how|why\s+then|how\s+then|what\s+then|wherefore\s+then|it\s+may\s+be\s+asked|saith\s+one|some\s+one\s+will\s+say|one\s+may\s+ask|why\s+does|how\s+can)\b/i;
const quoted=/["“”][^"“”]{0,240}\?/;
const notes=/(?:\[[^\]]{0,150}\]|\b(?:R\.\s*V\.|A\.\s*V\.|see also|cf\.|editor|translator|margin|note|MS\.|MSS\.|ed\.|footnote)\b)/i;
const greekish=/[\u0370-\u03ff]|(?:[A-Za-z][0-9/][A-Za-z0-9/]){3,}/;
function rateQuestion(q,lines){
 const line=q.originalQuestionLineOCR,clean=phrase(line);
 const questionPart=clean.slice(0,clean.indexOf("?")+1);
 const near=lines.slice(Math.max(0,q.ocrLine-4),Math.min(lines.length,q.ocrLine+3)).join(" ");
 const evidence=[];
 let points=0;
 if(strong.test(questionPart)){points+=5;evidence.push("explicit_interrogative_or_objection_cue")}
 else if(questionWords.test(questionPart)){points+=3;evidence.push("interrogative_word_in_OCR_line")}
 else{points-=1;evidence.push("no_explicit_interrogative_word")}
 if(/^(?:But|And|For|What|Why|How|Whence|Wherefore)\b/i.test(clean)){
  points++;evidence.push("line_begins_discourse_cue")
 }
 if(/(?:it\s+may\s+be\s+asked|saith\s+one|some\s+one\s+will\s+say)/i.test(clean)){
  points+=3;evidence.push("explicit_reported_question_frame")
 }
 if(quoted.test(near)){points-=3;evidence.push("nearby_quote_may_be_scripture_or_dialogue")}
 if(notes.test(near)){points-=2;evidence.push("possible_editorial_apparatus_nearby")}
 if(greekish.test(line)){points-=2;evidence.push("unusual_OCR_transliteration_or_mixed_script")}
 if(q.screeningFlags.length){points-=2;evidence.push("previous_source_layer_warnings")}
 if(questionPart.length<20){points-=1;evidence.push("short_question_line_or_column_fragment")}
 const flags=[...new Set([...q.screeningFlags,...evidence.filter(x=>
  x.startsWith("nearby_")||x.startsWith("possible_")||x.startsWith("unusual_"))])];
 if(q.workUnitId?.startsWith("schaff.npnf1-06.")){
  flags.push("two_column_harmony_OCR_alignment_unresolved");
  evidence.push("possible_scripture_interleaved_across_scan_columns");
 }
 return {preliminaryScore:points,positiveCueEvidence:evidence,
  sourceLayerRisks:flags,
  screeningClass:points>=5?"higher_priority_source_inspection":
   points>=2?"medium_priority_source_inspection":"low_priority_or_quoted_text",
  authorshipCertified:false,sourceReplyCertified:false};
}
function buildEnvelope(q,u,lines){
 const from=Math.max(q.ocrLine-10,u.startLine),
  to=Math.min(q.ocrLine+34,u.endLine);
 const originalOCRText=lines.slice(from-1,to).join("\n");
 return {sourceLineStart:from,sourceLineEnd:to,verbatimOCRText:originalOCRText,
  verbatimOCRSHA256:sha(originalOCRText),
  queryLineOffset:q.ocrLine-from,
  textRole:"neighboring_unverified_OCR_not_a_verified_answer",
  sourceOwnedWordsOnly:false,
  containsPotentialBibleAndEditorialText:true
 };
}
const workIds=["NPNF1-06","NPNF1-10"];
const perVolume=[],pilot=[];
for(const editionId of workIds){
 const unit=load(join(unitDir,editionId+".source-units-and-questions.v1.json"));
 const original=readFileSync(join(sourceDir,editionId+".raw-ocr.txt"),"utf8");
 if(sha(original)!==unit.sourceVolumeSHA256)throw Error("FULL_VOLUME_OCR_CHANGED");
 const lines=original.replace(/\r/g,"").split("\n");
 const all=unit.questions.map(q=>({...q,...rateQuestion(q,lines)}));
 const perUnit=[];
 for(const u of unit.units){
  const inside=all.filter(q=>q.workUnitId===u.id),
   eligible=inside.filter(q=>q.positiveCueEvidence.includes("explicit_interrogative_or_objection_cue")||
    q.positiveCueEvidence.includes("interrogative_word_in_OCR_line"));
  const ranked=eligible.sort((a,b)=>b.preliminaryScore-a.preliminaryScore||
   a.ocrLine-b.ocrLine);
  const max=editionId==="NPNF1-06"?8:2,selected=[];
  for(const q of ranked){
   if(selected.length>=max)break;
   if(selected.some(x=>Math.abs(x.ocrLine-q.ocrLine)<30))continue;
   selected.push(q);
  }
  if(!selected.length&&ranked.length)selected.push(ranked[0]);
  const emitted=selected.sort((a,b)=>a.ocrLine-b.ocrLine).map(q=>({
   id:q.id,editionId,workUnitId:u.id,workUnitLabel:u.unitLabel,
   originalLineNumber:q.ocrLine,originalQuestionLineOCR:q.originalQuestionLineOCR,
   originalQuestionLineSHA256:q.originalQuestionLineSHA256,
   preliminaryScreening:rateQuestion(q,lines),
   contextEnvelope:buildEnvelope(q,u,lines),
   columnAlignmentValidated:false,
   questionAndReplySpeakerSeparated:false,
   originalPrintedPageChecked:false,
   lexicalCatenaOverlapHints:q.lexicalCatenaOverlapHints,
   fatherAuthorshipEstablished:false,sourceOwnedReplyLocated:false,
   catenaNoveltyEstablished:false,publicationEligible:false
  }));
  pilot.push(...emitted);
  perUnit.push({workUnitId:u.id,questionCandidates:inside.length,
   sourceLayerWarned:inside.filter(x=>x.screeningClass==="low_priority_or_quoted_text").length,
   prioritizedOriginalContextEnvelopes:emitted.length});
 }
 perVolume.push({editionId,unitCount:unit.units.length,candidates:all.length,
  screeningBreakdown:Object.fromEntries(["higher_priority_source_inspection",
   "medium_priority_source_inspection","low_priority_or_quoted_text"].map(k=>
   [k,all.filter(q=>q.screeningClass===k).length])),
  perUnit,firstPartyTextCertified:0,contextEnvelopes:pilot.filter(p=>p.editionId===editionId).length});
}
const showcase=pilot.find(x=>x.editionId==="NPNF1-10"&&x.originalLineNumber===3086);
const explicitDemonstration={
 editionId:"NPNF1-10",sourceUnitId:"schaff.npnf1-10.matthew-homily-03",
 originalLineNumber:3086,
 sourceQuestionFromOCR:"But  what  kind  of  marvel  ?  it  may  be  asked.",
 exactNearbyOCRLineRange:[3086,3092],
 originalText:original=>original
};
const sourceLines=readFileSync(join(sourceDir,"NPNF1-10.raw-ocr.txt"),"utf8")
 .replace(/\r/g,"").split("\n");
const verbatim=sourceLines.slice(3085,3092).join("\n");
if(phrase(sourceLines[3085])!=="But what kind of marvel ? it may be asked."||
 !/That\s+the\s+Virgin\s+should\s+be\s+preserved/i.test(
 sourceLines.slice(3086,3091).join(" ")))throw Error("CHRYSOSTOM_III_EXPLICIT_EXAMPLE_NOT_FOUND");
delete explicitDemonstration.originalText;
explicitDemonstration.originalOCRText=verbatim;
explicitDemonstration.originalOCRSHA256=sha(verbatim);
explicitDemonstration.sourceStatus="printed_translation_question_and_adjacent_words_attested_in_scan_OCR_not_critical_source_checked";
explicitDemonstration.published=false;
const data={schema:"ao.catena.schaff-question-source-layer-pilot.v1",
 sourceEdition:"1888 Schaff NPNF first-series print OCR",
 scope:"4 Augustine Harmony books and 90 Chrysostom Matthew homilies",
 researchStatus:"all_attribution_and_answers_pending_source_page_disambiguation",
 questionWindowCount:perVolume.reduce((s,x)=>s+x.candidates,0),
 excerptWindowCount:pilot.length,
 sourceAuthorshipCertified:0,sourceRepliesCertified:0,catenaNoveltyConfirmed:0,
 harmonyColumnInterleavingUnresolved:true,
 chrysostomPrintedNotesUnresolved:true,
 approvals:0,unchangedOriginalOCR:true,
 volumes:perVolume,showcase:explicitDemonstration,selected:pilot};
mkdirSync(outDir,{recursive:true});
writeFileSync(join(outDir,"question-source-layer-pilot.v1.json"),JSON.stringify(data,null,2)+"\n");
const report={schema:"ao.catena.schaff-question-layer-summary.v1",
 totalQuestionWindows:data.questionWindowCount,
 contextEnvelopes:data.excerptWindowCount,
 perVolume:perVolume.map(x=>({
  editionId:x.editionId,unitCount:x.unitCount,candidates:x.candidates,
  screeningBreakdown:x.screeningBreakdown,
  contextEnvelopes:x.contextEnvelopes})),
 certifiedFatherQuestions:0,certifiedSourceReplies:0,confirmedCatenaNovelty:0,
 harmonyColumnInterleavingUnresolved:true,chrysostomPrintedNotesUnresolved:true,
 publicationApprovals:0};
writeFileSync(join(outDir,"summary.v1.json"),JSON.stringify(report,null,2)+"\n");
console.log(JSON.stringify(report));
